// Host object from the Nova scheduler pipeline.
// See: https://github.com/sapcc/nova/blob/stable/xena-m3/nova/scheduler/host_manager.py class HostState
type ExternalSchedulerHost struct {
	// Name of the Nova compute host, e.g. nova-compute-bb123.
	ComputeHost string `json:"host"`
	// Name of the hypervisor hostname, e.g. domain-c123.<uuid>
	HypervisorHostname string `json:"hypervisor_hostname"`
}

// Request generated by the Nova scheduler when calling cortex.
// The request contains a spec of the VM to be scheduled, a list of hosts and
// their status, and a map of weights that were calculated by the Nova weigher
// pipeline. Some additional flags are also included.
type ExternalSchedulerRequest struct {
	Spec NovaObject[NovaSpec] `json:"spec"`

	// Request context from Nova that contains additional meta information.
	Context NovaRequestContext `json:"context"`

	Hosts   []ExternalSchedulerHost `json:"hosts"`
	Weights map[string]float64      `json:"weights"`

	// The name of the pipeline to execute.
	Pipeline string `json:"pipeline"`

	// Options configure the pipeline behavior for this scheduling call.
	// Set by the caller (CR controller, failover controller, Nova).
	// Nova does not set these; Cortex fills in config-derived defaults server-side.
	Options scheduling.Options `json:"options,omitempty"`
}

func (r ExternalSchedulerRequest) GetOptions() scheduling.Options { return r.Options }
func (r ExternalSchedulerRequest) GetHosts() []string {
	hosts := make([]string, len(r.Hosts))
	for i, host := range r.Hosts {
		hosts[i] = host.ComputeHost
	}
	return hosts
}
func (r ExternalSchedulerRequest) GetWeights() map[string]float64 {
	return r.Weights
}
func (r ExternalSchedulerRequest) GetTraceLogArgs() []any {
	greq := ""
	if r.Context.GlobalRequestID != nil {
		greq = *r.Context.GlobalRequestID
	}
	return []any{
		"greq", greq,
		"req", r.Context.RequestID,
		"user", r.Context.UserID,
		"project", r.Context.ProjectID,
	}
}
func (r ExternalSchedulerRequest) Filter(includedHosts map[string]float64) lib.FilterWeigherPipelineRequest {
	filteredHosts := make([]ExternalSchedulerHost, 0, len(includedHosts))
	for _, host := range r.Hosts {
		if _, exists := includedHosts[host.ComputeHost]; exists {
			filteredHosts = append(filteredHosts, host)
		}
	}
	r.Hosts = filteredHosts
	// Also filter the weights map to only include the hosts that are still
	// in the request, and update the weights accordingly.
	filteredWeights := make(map[string]float64, len(includedHosts))
	for host, weight := range includedHosts {
		if _, exists := includedHosts[host]; exists {
			filteredWeights[host] = weight
		}
	}
	r.Weights = filteredWeights
	return r
}

// IsForcedDestination reports whether Nova forced this request onto specific
// hosts/nodes and the scheduler filters should be skipped entirely.
//
// This replicates Nova's native behavior: when force_hosts or force_nodes is
// set and the scheduler hint "_nova_check_type" is not set, Nova skips the
// filters and returns only the forced destinations.
// See: https://github.com/sapcc/nova/blob/05f384a938e3d6a8740a8f404d79d767d6ebdbd7/nova/scheduler/host_manager.py#L610-L620
func (r ExternalSchedulerRequest) IsForcedDestination() bool {
	forceHosts := r.Spec.Data.ForceHosts != nil && len(*r.Spec.Data.ForceHosts) > 0
	forceNodes := r.Spec.Data.ForceNodes != nil && len(*r.Spec.Data.ForceNodes) > 0
	if !forceHosts && !forceNodes {
		return false
	}
	// If _nova_check_type is set (e.g. rebuild/evacuate/resize), the host is
	// forced but must still be validated by the filters, so don't skip.
	checkType, err := r.Spec.Data.GetSchedulerHintStr("_nova_check_type")
	if err == nil && checkType != "" {
		return false
	}
	return true
}

// ForcedHosts returns the subset of request hosts that match the forced
// destinations (force_hosts / force_nodes). Matching mirrors Nova:
//   - force_hosts matches on the compute host name, case-insensitive.
//   - force_nodes matches on the hypervisor hostname, case-sensitive.
//   - When both are set, a host must match both (intersection).
//
// The returned slice preserves the order of the request hosts. If nothing
// matches, an empty slice is returned (Nova would then raise NoValidHost).
func (r ExternalSchedulerRequest) ForcedHosts() []string {
	var forceHosts []string
	if r.Spec.Data.ForceHosts != nil {
		forceHosts = *r.Spec.Data.ForceHosts
	}
	var forceNodes []string
	if r.Spec.Data.ForceNodes != nil {
		forceNodes = *r.Spec.Data.ForceNodes
	}
	forceHostSet := make(map[string]bool, len(forceHosts))
	for _, h := range forceHosts {
		forceHostSet[strings.ToLower(h)] = true
	}
	forceNodeSet := make(map[string]bool, len(forceNodes))
	for _, n := range forceNodes {
		forceNodeSet[n] = true
	}
	matched := make([]string, 0, len(r.Hosts))
	// Candidates are (host, node) pairs, so a single compute host may appear
	// multiple times (once per node). Deduplicate by compute host name, since
	// the response only carries host names.
	seen := make(map[string]bool, len(r.Hosts))
	for _, host := range r.Hosts {
		if len(forceHostSet) > 0 && !forceHostSet[strings.ToLower(host.ComputeHost)] {
			continue
		}
		if len(forceNodeSet) > 0 && !forceNodeSet[host.HypervisorHostname] {
			continue
		}
		key := strings.ToLower(host.ComputeHost)
		if seen[key] {
			continue
		}
		seen[key] = true
		matched = append(matched, host.ComputeHost)
	}
	return matched
}

type FlavorType string

const (
	// FlavorTypeGeneralPurpose represents general purpose workloads.
	FlavorTypeGeneralPurpose FlavorType = "general-purpose"
	// FlavorTypeHANA represents HANA workloads.
	FlavorTypeHANA FlavorType = "hana"
)

// GetFlavorType determines the flavor type based on the requested flavor's extra specs.
func (r ExternalSchedulerRequest) GetFlavorType() (FlavorType, error) {
	extraSpecs := r.Spec.Data.Flavor.Data.ExtraSpecs
	val, ok := extraSpecs["trait:CUSTOM_HANA_EXCLUSIVE_HOST"]
	if !ok {
		return FlavorTypeGeneralPurpose, nil
	}
	// If the key is provided, it must be either "required" or "forbidden".
	switch strings.ToLower(val) {
	case "forbidden":
		return FlavorTypeGeneralPurpose, nil
	case "required":
		return FlavorTypeHANA, nil
	default:
		return "", fmt.Errorf("unsupported value for trait:CUSTOM_HANA_EXCLUSIVE_HOST in flavor extra specs: %s", val)
	}
}

type HypervisorType string

const (
	// HypervisorTypeQEMU represents QEMU/KVM hypervisors.
	HypervisorTypeQEMU HypervisorType = "qemu"
	// HypervisorTypeCH represents Cloud-Hypervisor/KVM hypervisors.
	HypervisorTypeCH HypervisorType = "ch"
	// HypervisorTypeVMware represents VMware hypervisors.
	HypervisorTypeVMware HypervisorType = "vmware"
)

// GetHypervisorType determines the hypervisor type based on the requested flavor.
func (req ExternalSchedulerRequest) GetHypervisorType() (HypervisorType, error) {
	extraSpecs := req.Spec.Data.Flavor.Data.ExtraSpecs
	if val, ok := extraSpecs["capabilities:hypervisor_type"]; ok {
		switch strings.ToLower(val) {
		case "qemu":
			return HypervisorTypeQEMU, nil
		case "ch":
			return HypervisorTypeCH, nil
		case "vmware vcenter server":
			return HypervisorTypeVMware, nil
		}
		return "", fmt.Errorf("unsupported hypervisor_type: %s", val)
	}
	return "", errors.New("hypervisor type not specified in flavor extra specs")
}

// IsKVMRequest determines whether the request is intended for a KVM-based hypervisor.
// If no hypervisor type is specified or an error occurs, it returns false.
func (req ExternalSchedulerRequest) IsKVMRequest() bool {
	hvType, err := req.GetHypervisorType()
	if err != nil {
		return false
	}
	return hvType == HypervisorTypeQEMU || hvType == HypervisorTypeCH
}

// The helpers below resolve Nova's loosely-typed flavor extra-spec string
// conventions into the typed values the scheduling pipeline consumes. They live
// here, with the Nova wire message types, because the "trait:"/"capabilities:"/
// "accel:" key conventions are Nova's — not the pipeline's. Both the Nova wire
// adapter and the in-process reservation controllers (which hold a flavor's
// extra-spec map directly) call them, so the conventions are understood in exactly
// one place.

// unsupportedCapabilityOps are the Nova extra-spec comparison operators the
// capabilities filter does not implement. A capability value containing any of
// these means the request uses an advanced match the pipeline can't honor, so
// SplitCapabilities drops capabilities entirely (the filter then becomes a
// no-op), matching Nova's "skip" behavior.
// See: https://github.com/sapcc/nova/blob/3ebf80/nova/scheduler/filters/extra_specs_ops.py#L23
var unsupportedCapabilityOps = []string{
	"=", "<in>", "<all-in>", "==", "!=", ">=", "<=",
	"s==", "s!=", "s<", "s<=", "s>", "s>=", "<or>",
}

// SplitTraits splits a flavor's "trait:<name>" extra specs into required and
// forbidden trait names, classified by the "required"/"forbidden" value.
func SplitTraits(extraSpecs map[string]string) (required, forbidden []string) {
	for key, value := range extraSpecs {
		name, ok := strings.CutPrefix(key, "trait:")
		if !ok {
			continue
		}
		switch value {
		case "required":
			required = append(required, name)
		case "forbidden":
			forbidden = append(forbidden, name)
		}
	}
	return required, forbidden
}

// SplitCapabilities extracts a flavor's "capabilities:<key>" extra specs as typed
// compute.Capability equalities (prefix stripped). The "hypervisor_type" value is
// canonicalized (qemu->QEMU, ch->CH) so it matches what hypervisors advertise
// (filter_capabilities compares case-sensitively); all other values pass through
// unchanged. If any value uses an unsupported comparison operator it returns nil so
// the capabilities filter is skipped entirely (matching Nova behavior).
func SplitCapabilities(extraSpecs map[string]string) []compute.Capability {
	var caps []compute.Capability
	for key, value := range extraSpecs {
		name, ok := strings.CutPrefix(key, "capabilities:")
		if !ok {
			continue
		}
		for _, op := range unsupportedCapabilityOps {
			if strings.Contains(value, op) {
				return nil // Unsupported operator: skip the whole filter.
			}
		}
		if name == "hypervisor_type" {
			value = CanonicalHypervisorType(value)
		}
		caps = append(caps, compute.Capability{Name: name, Value: value})
	}
	return caps
}

// CanonicalHypervisorType normalizes a flavor's capabilities:hypervisor_type value
// to the casing hypervisors advertise (QEMU/CH), since filter_capabilities compares
// values case-sensitively. Unrecognized values pass through unchanged.
func CanonicalHypervisorType(value string) string {
	switch strings.ToLower(value) {
	case "qemu":
		return "QEMU"
	case "ch":
		return "CH"
	default:
		return value
	}
}

// RequestsAccelerators reports whether a flavor requests a hardware accelerator,
// resolved from the presence of the "accel:device_profile" extra spec.
func RequestsAccelerators(extraSpecs map[string]string) bool {
	_, ok := extraSpecs["accel:device_profile"]
	return ok
}

const (
	// LiveMigrationIntent indicates that the request is intended for live migration.
	LiveMigrationIntent v1alpha1.SchedulingIntent = "live_migration"
	// RebuildIntent indicates that the request is intended for rebuilding a VM.
	RebuildIntent v1alpha1.SchedulingIntent = "rebuild"
	// ResizeIntent indicates that the request is intended for resizing a VM.
	ResizeIntent v1alpha1.SchedulingIntent = "resize"
	// EvacuateIntent indicates that the request is intended for evacuating a VM.
	EvacuateIntent v1alpha1.SchedulingIntent = "evacuate"
	// CreateIntent indicates that the request is intended for creating a new VM.
	CreateIntent v1alpha1.SchedulingIntent = "create"
	// ReserveForFailoverIntent indicates that the request is for creating a new failover reservation slot.
	ReserveForFailoverIntent v1alpha1.SchedulingIntent = "reserve_for_failover"
	// ReuseFailoverReservationIntent indicates that the request is checking whether an existing
	// failover reservation slot can be reused by a VM (compatibility check, not a new slot).
	ReuseFailoverReservationIntent v1alpha1.SchedulingIntent = "reuse_failover_reservation"
	// ReserveForCommittedResourceIntent indicates that the request is for CR reservation scheduling.
	ReserveForCommittedResourceIntent v1alpha1.SchedulingIntent = "reserve_for_committed_resource"
	// CapacityProbeIntent indicates that the request is a synthetic capacity probe (not a real VM placement).
	CapacityProbeIntent v1alpha1.SchedulingIntent = "capacity_probe"

	// HintKeyResourceGroup is the scheduler hint key used to pass the resource group
	// (e.g., flavor group name) for failover reservation scheduling.
	// The weigher uses this to compare against existing reservations' ResourceGroup.
	HintKeyResourceGroup = "_cortex_resource_group"
)

// NovaIntents lists all scheduling intents relevant to Nova.
var NovaIntents = []v1alpha1.SchedulingIntent{
	LiveMigrationIntent,
	RebuildIntent,
	ResizeIntent,
	EvacuateIntent,
	CreateIntent,
}

// GetIntent analyzes the request spec and determines the intent of the scheduling request.
func (req ExternalSchedulerRequest) GetIntent() (v1alpha1.SchedulingIntent, error) {
	str, err := req.Spec.Data.GetSchedulerHintStr("_nova_check_type")
	if err != nil {
		return "", err
	}
	switch str {
	// See: https://github.com/sapcc/nova/blob/ba4813/nova/scheduler/utils.py#L1251
	case "rebuild":
		return RebuildIntent, nil
	// See: https://github.com/sapcc/nova/blob/ba4813/nova/scheduler/utils.py#L1264
	case "resize":
		return ResizeIntent, nil
	// See: https://github.com/sapcc/nova/blob/ba4813/nova/scheduler/utils.py#L1277C47-L1277C63
	case "live_migrate":
		return LiveMigrationIntent, nil
	// Added in https://github.com/sapcc/nova/pull/594
	// See: https://github.com/sapcc/nova/blob/c88393/nova/compute/api.py#L5770
	case "evacuate":
		return EvacuateIntent, nil
	// Used by cortex failover reservation controller
	case "reserve_for_failover":
		return ReserveForFailoverIntent, nil
	// Used by cortex failover reservation controller (reuse check)
	case "reuse_failover_reservation":
		return ReuseFailoverReservationIntent, nil
	// Used by cortex committed resource reservation controller
	case "reserve_for_committed_resource":
		return ReserveForCommittedResourceIntent, nil
	// Used by cortex capacity probe controller
	case "capacity_probe":
		return CapacityProbeIntent, nil
	default:
		return CreateIntent, nil
	}
}

// Response generated by cortex for the Nova scheduler.
// Cortex returns an ordered list of hosts that the VM should be scheduled on.
type ExternalSchedulerResponse struct {
	Hosts []string `json:"hosts"`
}

// Wrapped Nova object. Nova returns objects in this format.
type NovaObject[V any] struct {
	Name      string   `json:"nova_object.name"`
	Namespace string   `json:"nova_object.namespace"`
	Version   string   `json:"nova_object.version"`
	Data      V        `json:"nova_object.data"`
	Changes   []string `json:"nova_object.changes"`
}

type NovaObjectList[V any] struct {
	Objects []NovaObject[V] `json:"objects"`
}

// Spec object from the Nova scheduler pipeline. Fields unused by Nova are omitted.
// See: https://github.com/sapcc/nova/blob/stable/xena-m3/nova/objects/request_spec.py
type NovaSpec struct {
	ProjectID        string `json:"project_id"`
	UserID           string `json:"user_id"`
	InstanceUUID     string `json:"instance_uuid"`
	AvailabilityZone string `json:"availability_zone"`
	NumInstances     uint64 `json:"num_instances"`
	IsBfv            bool   `json:"is_bfv"`

	// Consider using GetSchedulerHintStr.
	SchedulerHints map[string]any `json:"scheduler_hints"`

	IgnoreHosts *[]string `json:"ignore_hosts"`
	ForceHosts  *[]string `json:"force_hosts"`
	ForceNodes  *[]string `json:"force_nodes"`

	Image              NovaObject[NovaImageMeta]          `json:"image"`
	Flavor             NovaObject[NovaFlavor]             `json:"flavor"`
	RequestLevelParams NovaObject[NovaRequestLevelParams] `json:"request_level_params"`
	NetworkMetadata    NovaObject[map[string]any]         `json:"network_metadata"`
	Limits             NovaObject[map[string]any]         `json:"limits"`
	RequestedNetworks  NovaObjectList[map[string]any]     `json:"requested_networks"`
	SecurityGroups     NovaObjectList[map[string]any]     `json:"security_groups"`

	NumaTopology         *NovaObject[NovaNumaTopology]         `json:"numa_topology"`
	RequestedDestination *NovaObject[NovaRequestedDestination] `json:"requested_destination"`
	InstanceGroup        *NovaObject[NovaInstanceGroup]        `json:"instance_group"`
}

// Hints can be a one-element list or a direct value.
// See: https://github.com/sapcc/nova/blob/3e715db/nova/objects/request_spec.py#L382
//
// This function is a convenience to extract the first element
// from the hints list or return the value directly if it's not a list.
func (s NovaSpec) GetSchedulerHintStr(key string) (string, error) {
	if s.SchedulerHints == nil {
		return "", errors.New("scheduler hints are not set")
	}
	raw, ok := s.SchedulerHints[key]
	if !ok {
		return "", fmt.Errorf("scheduler hint %q not found", key)
	}
	switch v := raw.(type) {
	case []any:
		if len(v) > 0 {
			if str, ok := v[0].(string); ok {
				return str, nil
			}
		}
	case string:
		return v, nil
	}
	return "", errors.New("unknown scheduler hint type")
}

